for {
    desired := getDesiredState(workloadSpec)    // 从 etcd 读取期望状态
    actual := getActualState(pods, replicas)    // 从集群收集实际状态
    if desired != actual {
        act(diff(desired, actual))              // 创建/删除 Pod 使实际趋近期望
    }
    sleep(reconcileInterval)
}

